import{_ as e,c as a,a2 as p,o}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第一百五十九章 纯正的黄金","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/159第一百五十九章 纯正的黄金.md","filePath":"meditation/巴利文大藏经/159第一百五十九章 纯正的黄金.md"}'),r={name:"meditation/巴利文大藏经/159第一百五十九章 纯正的黄金.md"};function _(n,t,i,s,d,c){return o(),a("div",null,t[0]||(t[0]=[p('<h1 id="第一百五十九章-纯正的黄金" tabindex="-1">第一百五十九章 纯正的黄金 <a class="header-anchor" href="#第一百五十九章-纯正的黄金" aria-label="Permalink to &quot;第一百五十九章 纯正的黄金&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部16相应13经/相似正法经(迦叶相应/因缘篇/如来记说)</p><p>有个时候，佛陀住在舍卫城的祇树林给孤独园，有一天，迦叶尊者来到佛陀的住处，顶礼佛陀后，迦叶尊者在一旁坐下，迦叶尊者对佛陀说：“世尊，为什么过去您制定的、管束修行人行为、言语、念想的戒律不多，却有很多修行人开启智慧，证悟各种不同的解脱果位呢？世尊，为什么现在您制定的戒律越来越多，可是开启智慧，证悟各种解脱果位的修行人却越来越少了呢？怎么您制定的戒律越多，这些修行人反而成就的更少了呢？我实在是想不明白，按道理来说戒律越多，开启智慧，证悟解脱果位的人应该越多呀，怎么会越变越少了呢？请世尊您为我讲解一下，为我排解疑惑。”</p><p>佛陀说：“迦叶！是这样的，因为修行的众生越来越少了，正法也在口口相传中逐渐的丧失了本来的面目。既然如此，因为世间诱惑、迷惑众生，让众生生起欲望的事物越来越多，每时每刻都可能会产生新的、诱惑、迷惑众生的事物，每时每刻都可能会产生新的、让众生生起欲望的事物，所以如来制定的戒律变的越来越多，目的是想通过戒律来管束众生的行为、言语、念想，以此让众生从这些事物中解脱出来，熄灭他们内心中的欲望之火，让他们的内心进入清净的境界。如来的正法是通过口口相传的，由于口传如来正法的时间长久后，或者口传如来正法的人没有领略到其中的义理，他们就会错传、错解如来的正法。更有一些人为了获得世间人的丰厚供养，就借用如来的名义，讲说一些如来从来都没有说过的法，他们按自己内心中的想象胡乱编造出一些毫无依据、毫无修行实践、不合乎因缘果报的神话、童话。他们已经把自己当成了如来。</p><p>迦叶！如来把这些错误的口传，没有正确理解如来正法义理的口传记录，甚至于这些为了获得世间人供养胡编乱造出来的毫无依据、毫无修行实践、不合乎因缘果报的神话、童话、虚假不真实的假法，都称为像法，也就是表面上看起来好像是如来的正法，实际上却不是，他们只是冒用了如来的名字，在讲说他们自己内心中想象出来的法。</p><p>迦叶！你要明白，一旦像法出现了，如来的正法就会慢慢的消失不见。如果像法大行其道，被世间所有的人接受、认可，那么如来的正法就会被灭尽。世间人会去相信那些包裹着漂亮装饰物的假法，去相信那些子虚乌有的神话、童话，不会再去传扬真实的如来正法，他们会陷入这些假法描述的境界之中，他们会被这些虚假的神话、童话所欺骗。从而丧失掉接触、听闻如来正法的机会。这样如来的正法就会灭尽、消失。</p><p>迦叶！就如同如果世间出现了掺入各种金属不纯正的黄金，出现了只有表面才覆盖有黄金的镀金，出现了形象像黄金、不是黄金却冒充黄金的金属。那些真正纯正的黄金就会逐渐消失不见。世间将会充斥着各种不纯正的黄金、各种镀金、各种根本不含有黄金却冒充黄金的金属。迦叶！同样的道理，当这些虚假的像法在世间广为流传的时候，如来的正法就会被替换掉，就不会再有人会接触、听闻到如来的正法，就不会再有人去弘扬如来的正法。这些弘扬虚假像法的人，他们还以为自己是在弘扬如来的正法，他们还会认为自己弘扬虚假像法的功德是无量无边的。他们哪里知道，他们弘扬虚假像法的行为其实是在破坏如来的正法。无数多的人因为他们弘扬虚假像法的行为，而被虚假像法毒害、污染。当这些被虚假像法毒害、污染的人无意中接触、听闻到如来真正的正法的时候，他们就会恶口诽谤、中伤如来的正法，因为如来的正法与他们接触到的虚假像法不一样、不相同，他们会抛弃如来的正法，继续沉浸在虚假的像法之中，他们会继续按虚假像法中错误的方法去修行。如来的正法没有人听闻，没有人弘扬，被虚假的像法替代掉，如来的正法就会由此逐渐的消失、灭尽。</p><p>迦叶！你要知道地界、水界、火界、风界（地界、水界、火界、风界解释，见第三十章）无法让如来的正法消失、灭尽，因为如来只是将世间的规则、真相说出来了而已。这些世间的规则、真相不管如来说不说，他们都是真实存在的。如来的正法说的就是这些世间的规则、真相。如来的正法只会在世间人或众生的念想、思想中消失、灭尽。这些愚昧无知的众生，他们错传如来的正法，他们错解如来的正法，他们胡编乱造出毫无依据、毫无修行实践、不合乎因缘果报的神话、童话、虚假不真实的假法。让世间人的念想、思想中污染了这些虚假的像法，让世间人的念想、思想中装入了这些虚假的像法，在他们的念想、思想中如来的正法已经消失，已经灭尽了，就算他们偶然听闻到了如来的正法，他们也会用这些虚假像法中的义理来破斥、反驳、拒绝接受如来的正法。如来的正法就被这些冒用如来的名字、身份，错传、错解、胡编乱造的虚假像法替代掉了，如来的正法就是这样在世间人的念想、思想中逐渐消失、灭尽的。</p><p>迦叶！如来正法的消失、灭尽不是立刻发生的，而是逐渐慢慢的发生的，就如同在江河上，海洋上行驶的船是慢慢沉入江河底的，是慢慢沉入海底的。世间的众生因为五种行为加速了如来正法的消失、灭尽，是哪五种行为呢？就是比丘（男性出家人）、比丘尼（女性出家人）、优婆塞（男性在家修行人）、优婆夷（女性在家修人），他们对讲解如来正法的人不尊敬、不遵从；他们对如来的正法不尊敬、不遵从；他们对僧团不尊敬、不遵从；他们不认真的学习和理解如来的正法，不实践的去修行如来的正法；他们不让自己的内心集中安住在清净的境界之中，他们胡思乱想、内心散乱。迦叶！这五种行为会导致如来的正法在世间众生的念想、思想中加速的消失、灭尽。</p><p>迦叶！有五种行为能够让如来的正法长久的保留在世间，并持续的弘扬下去，是哪五种行为呢？就是比丘（男性出家人）、比丘尼（女性出家人）、优婆塞（男性在家修行人）、优婆夷（女性在家修人），他们尊敬、遵从讲解如来正法的人；他们尊敬、遵从如来的正法；他们尊敬、遵从僧团；他们认真的学习和理解如来的正法，并实践的去修行如来的正法；他们让自己的内心集中安住在清净的境界之中，他们不胡思乱想，他们不让自己的内心散乱。迦叶！这五种行为会让如来的正法在世间众生的念想、思想中长久的驻留，并持续的弘扬下去。世间的众生也将会获得无数的功德法益，他们将会解除对世间一切事物的束缚捆绑，他们将会灭尽一切的烦恼和痛苦，他们将会从生死轮回中永远的解脱出来，他们将会达到不生不灭涅槃的境界。”</p><p>佛陀说法后，迦叶尊者再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，并按着佛陀所说的法去修行。</p>',12)]))}const f=e(r,[["render",_]]);export{m as __pageData,f as default};
